package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_getTextBuffer_TriageGen2Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    @Test
    public void testGetTextBuffer_SharedInputBuffer() {
        char[] sharedBuf = {'a', 'b', 'c'};
        // resetWithShared sets _inputStart >= 0
        textBuffer.resetWithShared(sharedBuf, 0, 3);

        char[] result = textBuffer.getTextBuffer();

        assertSame("Should return the shared input buffer", sharedBuf, result);
    }

    @Test
    public void testGetTextBuffer_ResultArrayNotNull() {
        // resetWithCopy populates _resultArray and sets _inputStart < 0
        char[] input = {'h', 'e', 'l', 'l', 'o'};
        textBuffer.resetWithCopy(input, 0, 5);

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertArrayEquals(input, result);
        // Ensure it's the internal _resultArray, not the original input
        assertNotSame(input, result);
    }

    @Test
    public void testGetTextBuffer_ResultStringNotNull() {
        // resetWithString populates _resultString and sets _resultArray to null initially
        String input = "jackson";
        textBuffer.resetWithString(input);

        char[] result = textBuffer.getTextBuffer();

        assertArrayEquals(input.toCharArray(), result);
        // Verify lazy initialization of _resultArray works by calling again
        assertSame("Second call should return the newly created _resultArray", result, textBuffer.getTextBuffer());
    }

    @Test
    public void testGetTextBuffer_SingleSegment() {
        // When not shared, not resultArray, not resultString, and not segmented
        // We use append to add data to the current segment
        textBuffer.append('t');
        textBuffer.append('e');
        textBuffer.append('s', 't'); // Note: append(char) exists, using logic to fill segment

        // To ensure _hasSegments is false, we just use the buffer without triggering segment transitions
        // In TextBuffer, _hasSegments is false if we haven't finished a segment yet

        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        // Since we haven't finished a segment or used the other paths, it returns _currentSegment
        // We can't easily check the exact array instance of _currentSegment without reflection, 
        // but we can verify it contains our data.
        String content = textBuffer.contentsAsString();
        assertEquals("test", content);
    }

    @Test
    public void testGetTextBuffer_MultiSegment() {
        // To trigger _hasSegments = true, we must finish a segment
        // We append enough to exceed the default segment size or manually finish it
        textBuffer.append('a');
        textBuffer.finishCurrentSegment();
        textBuffer.append('b');

        // Now _hasSegments is true, and it's not shared/resultArray/resultString
        // It should call contentsAsArray()
        char[] result = textBuffer.getTextBuffer();

        assertNotNull(result);
        assertEquals("ab", new String(result));
    }
}
